549	          snap.fields.find(f => f.key === "important_date").op === "set" &&
550	          snap.fields.find(f => f.key === "important_date").value === "2023-02-29" &&
551	          !snap.fields.find(f => f.key === "important_date").disabled,
552	          snap.fields);
553	        check("F 拒绝：按钮恢复「保存修改」且因仍有勾选保持可提交",
554	          snap.submitText === "保存修改" && !snap.submitDisabled,
555	          {text: snap.submitText, disabled: snap.submitDisabled});
556	        check("F 拒绝：表格未被清理、无空列表/读取失败提示",
557	          snap.rows.length === 3 && !snap.emptyOn && !snap.loadErrorOn,
558	          {rows: snap.rows.length, empty: snap.emptyOn, err: snap.loadErrorOn});
559	
560	        const real = await listClients(base);
561	        check("F 拒绝：后端未被部分写入（来源保持拒绝前的值、行业未被清空）",
562	          real.clients.find(x => x.id === a).source === "再改一次" &&
563	          real.clients.find(x => x.id === b).source === "页面新来源" &&
564	          real.clients.find(x => x.id === a).industry === "行业-no-clients",
565	          {a: real.clients.find(x => x.id === a).source,
566	           b: real.clients.find(x => x.id === b).source});
567	
568	        // 用户修正日期后再次保存：保留的勾选与填写直接可用，成功后正常清理
569	        await page.evaluate(() => {
570	          const card = document.querySelector('#batch-fields .bf[data-field="important_date"]');
571	          card.querySelector(".bf-value").value = "2024-02-29";
572	        });
573	        await saveAndSettle(session);
574	        const fixed = await snapshot(page);
575	        check("F 修正后：用保留的勾选与填写再次保存成功（2 名）并完成清理",
576	          successBanner(fixed, 2) && cleanedUp(fixed),
577	          {banners: fixed.banners, sel: fixed.selCount, fields: fixed.fields});
578	        await page.close();
579	      }
580	
581	      // ===================================================================
582	      // 场景 G：成功数量严格以保存回复为准，不按刷新后的记录数计算
583	      //         （保存回复 5 名，但列表只有 3 行）
584	      // ===================================================================
585	      {
586	        const session = await openSession(browser, base);
587	        const {page, modes} = session;
588	        await selectRows(page, [a]);
589	        await chooseSet(page, "region", "数量以回复为准");
590	        modes.batchOverride = {status: 200, body: JSON.stringify({updated_count: 5})};
591	        await saveAndSettle(session);
592	        const snap = await snapshot(page);
593	
594	        check("G 回复 5 名/表格 3 行/勾选 1 名：页面显示 5 名且说明列表已更新",
595	          snap.banners.some(x => x.cls.includes("ok") &&
596	            /已成功处理\s*5\s*名客户/.test(x.text) && x.text.includes("列表已更新")),
597	          snap.banners);
598	        check("G 回复 5 名：勾选与编辑同样完成清理、按钮恢复禁用",
599	          cleanedUp(snap), {sel: snap.selCount, fields: snap.fields});
600	        await page.close();
601	      }
602	
603	      // ===================================================================
604	      // 场景 H：真实空列表正常显示空列表提示；空库时读取失败不伪造空列表
605	      // ===================================================================
606	      {
607	        const {proc: emptyProc, port: emptyPortP} = startApp("empty");
608	        try {
609	          const emptyBase = `http://127.0.0.1:${await emptyPortP}`;
610	          await waitReady(emptyBase);
611	
