613	          const {page, modes} = session;
614	          const snap = await snapshot(page);
615	          check("H 真实空列表：显示「还没有客户记录」",
616	            snap.emptyOn && snap.rows.length === 0, {empty: snap.emptyOn, rows: snap.rows});
617	          check("H 真实空列表：表格隐藏、无读取失败提示",
618	            snap.tableDisplay !== "table" && !snap.loadErrorOn,
619	            {display: snap.tableDisplay, err: snap.loadErrorOn});
620	          check("H 真实空列表：已选 0、保存按钮禁用",
621	            snap.selCount === "0" && snap.submitDisabled,
622	            {sel: snap.selCount, disabled: snap.submitDisabled});
623	
624	          // 空库时首屏读取失败：不得把连接失败误判成真实空列表
625	          modes.list = "close";
626	          await page.goto(emptyBase + "/", {waitUntil: "domcontentloaded"});
627	          await page.waitForSelector("#clients-load-error.on", {timeout: 5000});
628	          const failSnap = await snapshot(page);
629	          check("H 空库读取失败：显示读取失败提示", failSnap.loadErrorOn, failSnap.loadErrorText);
630	          check("H 空库读取失败：不显示「还没有客户记录」、表格不出现",
631	            !failSnap.emptyOn && failSnap.tableDisplay !== "table",
632	            {empty: failSnap.emptyOn, display: failSnap.tableDisplay});
633	
