        check(`C ${mode}：保存请求未重发`,
          session.counts.batchPosts === beforePosts + 1, session.counts.batchPosts);
        check(`C ${mode}：后端行业确已保存（去前后空白）`,
          (await listClients(base)).clients.find(x => x.id === a).industry ===
            `行业-${mode}`,
          "后端 industry");
