        await chooseSet(page, "important_date", "2024-02-29");
        const beforePosts = session.counts.batchPosts;
        await saveAndSettle(session);
        const snap = await snapshot(page);

        check("E 正常路径：显示已成功处理 2 名且说明列表已更新",
